<?php
defined('ROOT') || exit;
/* print the user sidebar and open the main area.
   $act = the page being shown. $back = optional url: phones then swap the bottom tab bar for a slim top bar
   (back button on the left, Unsent logo in the middle). Used by the write page and an open chat. */
function page_start($act, $back = null, $title = '')
{
    global $me;
    /* phone tab bar = Home, Friends, Profile. Write is kept in the desktop sidebar only (class dsk). */
    $n = ['home' => ['Home', 'home', '?p=home'], 'write' => ['Write', 'pen', '?p=write', 'dsk'], 'friends' => ['Friends', 'users', '?p=friends'], 'profile' => ['Profile', 'user', '?p=space']];
    if (is_admin()) $n['admin'] = ['Admin', 'shield', '?p=admin'];
    /* sub pages light up the tab they belong to */
    $tab = ['mood' => 'home', 'unsent' => 'home', 'editor' => 'write', 'space' => 'profile', 'chat' => 'friends'][$act] ?? $act;
    echo '<div class="app' . ($back ? ' sub' : '') . ($back && $title ? ' titled' : '') . '"><aside><div>' . ($back ? '<a class=topback href="' . esc($back) . '" aria-label="Back">' . icon('arrowl', 22) . '</a>' : '') . ($back && $title ? '<span class=toptitle>' . esc($title) . '</span>' : '') . '<a class=toplogo href="?p=home"><img class=logo src=img/logo.png alt=Unsent></a><nav>';
    $unread = unread_count((int)($me['_id'] ?? 0));
    foreach ($n as $k => $v) echo "<a href='{$v[2]}' aria-label='{$v[0]}'" . ($k == $tab ? ' aria-current=page' : '') . " class='" . ($k == $tab ? 'on' : '') . (!empty($v[3]) ? ' ' . $v[3] : '') . ($k == 'profile' ? ' pf' : '') . "'>" . ($k == 'profile' ? '<span class=navav>' . avatar_html($me) . '</span>' : '') . icon($v[1], 20) . ($k == 'profile' ? '<span class=pl>' . $v[0] . '</span>' : $v[0]) . ($k == 'friends' && $unread ? "<em class=nb id=navnb>$unread</em>" : '') . "</a>";
    echo '</nav>' . '<script>(function(){try{var n=document.querySelector("aside nav");if(!n)return;var ph=matchMedia("(max-width:900px)").matches;function R(){var a=n.querySelector("a.on");if(!a)return null;var r=a.getBoundingClientRect(),b=n.getBoundingClientRect();if(!r.width)return null;return{l:r.left-b.left,w:r.width,t:r.top-b.top,h:r.height}}addEventListener("pagehide",function(){try{var r=R();if(r&&ph)sessionStorage.setItem("dk",JSON.stringify({r:r,t:Date.now()}));else sessionStorage.removeItem("dk")}catch(x){}});if(!ph)return;var d=JSON.parse(sessionStorage.getItem("dk")||"null");sessionStorage.removeItem("dk");if(!d||Date.now()-d.t>8000||!n.animate)return;if(matchMedia("(prefers-reduced-motion:reduce)").matches||document.documentElement.hasAttribute("data-calm"))return;var to=R();if(!to||(Math.abs(d.r.l-to.l)<2&&Math.abs(d.r.w-to.w)<2))return;var p=document.createElement("i");p.className="dkp";p.style.cssText="top:"+to.t+"px;height:"+to.h+"px;left:"+d.r.l+"px;width:"+d.r.w+"px";n.insertBefore(p,n.firstChild);n.classList.add("glide");var end=function(){n.classList.remove("glide");p.remove()};var a=p.animate([{left:d.r.l+"px",width:d.r.w+"px"},{left:to.l+"px",width:to.w+"px"}],{duration:440,easing:"cubic-bezier(.3,1.08,.35,1)",fill:"forwards"});a.onfinish=end;a.oncancel=end;setTimeout(end,900)}catch(x){}})()</script>' . '</div>' . notify_markup() . '<div class=foot2><div class=quote>' . icon('spark', 18) . '<p class=hand>Some words feel lighter once they\'re written.</p></div><div class=mew><div class=menu id=mem role=menu hidden><a role=menuitem href="?p=space"' . ($act == 'space' ? ' aria-current=page' : '') . '>' . icon('user', 17) . 'Your space</a><a role=menuitem href="?p=unsent"' . ($act == 'unsent' ? ' aria-current=page' : '') . '>' . icon('mail', 17) . 'Unsent drafts</a><a role=menuitem href="?p=profile#profile">' . icon('sliders', 17) . 'Settings</a><a role=menuitem href="?p=profile#appearance">' . icon('palette', 17) . 'Preferences</a><form method=post><input type=hidden name=a value=logout><button role=menuitem class=out>' . icon('out', 17) . 'Log out</button></form></div><button type=button class=me id=meb aria-label="Profile menu" aria-haspopup=menu aria-expanded=false aria-controls=mem>' . avatar_html($me) . '<span><b>' . esc($me['name']) . (is_admin() ? ' <em class="rb adm">Admin</em>' : '') . '</b><small>' . esc($me['email']) . '</small></span>' . icon('dots', 18) . '</button></div></div></aside><main id=main tabindex=-1>';
}
